mapper.select:
select * from system_app_versions
where platform = #{platform}
order by version_code desc

mapper.update:
update system_app_versions
platform=#{platform}, version_code=#{versionCode}, version_name=#{versionName}, min_compatible_code=#{minCompatibleCode}, download_url=#{downloadUrl}, apk_md5=#{apkMd5}, release_notes=#{releaseNotes}, update_strategy=#{updateStrategy}, is_published=#{isPublished}, publish_time=#{publishTime},
where id = #{id}
